96	/**
97	 * A sheet's dated settings: for each key (floor, late-pct, terms, terms-&lt;grade&gt;, clerk-limit, cap) the values
98	 * recorded, by from-date (a value null: blank). The value in force on a date is the one with the latest from-date on or
99	 * before it; before every from-date it is the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none
100	 * for the clerk limit, the cap and a grade's own terms).
101	 */
102	public record DatedSettings(Map<String, NavigableMap<LocalDate, String>> values) {
103	
104	    public static final String FLOOR = "floor";
105	    public static final String LATE_PCT = "late-pct";
106	    public static final String TERMS = "terms";
107	    public static final String CLERK_LIMIT = "clerk-limit";
108	    public static final String CAP = "cap";
109	
110	    /** The key of a grade's own terms. */
111	    public static String gradeTerms(String grade) {
112	        return TERMS + "-" + grade;
113	    }
114	
115	    /** The audit field for a from-date typed with a save, " from=<date>", or "" when none was typed (the sheet's today). */
116	    public static String auditFrom(LocalDate from) {
117	        return from == null ? "" : " from=" + from;
118	    }
119	
120	    /** The date a value saved with this from-date (null: none typed) is recorded from: it, else the sheet's today. */
121	    public static LocalDate fromOr(LocalDate from, LocalDate today) {
122	        return from == null ? today : from;
123	    }
124	
125	    /** One value recorded from a date. */
126	    public record FromValue(LocalDate from, String value) {
127	    }
128	
129	    /** The value of the key in force on the date (null: blank, or nothing recorded on or before it). */
130	    private String on(String key, LocalDate date) {
131	        NavigableMap<LocalDate, String> recorded = values.get(key);
132	        if (recorded == null || date == null) {
133	            return null;
134	        }
135	        Map.Entry<LocalDate, String> entry = recorded.floorEntry(date);
136	        return entry == null ? null : entry.getValue();
137	    }
138	
139	    /** The floor in force on the date. */
