336	public class ValidateSettingsRequest {
337	
338	    /** 0.00 or more, with at most two decimals. */
339	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}(\\.\\d{1,2})?|\\.\\d{1,2}");
340	
341	    /** A percent: 0.00 or more, with at most two decimals. */
342	    private static final Pattern PERCENT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");
343	
344	    /** The grades terms can be set for. */
345	    private static final Set<String> GRADES = Set.of("A", "B", "C");
346	
347	    /** 0 or more whole days. */
348	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
349	
350	    public void validate(@RequestBody @Valid SettingsRequest request, Out<ClerkLimit> limit, Out<Floor> floor,
351	            Out<Terms> terms, Out<LatePct> latePct, Out<PolicyDate> policyDate,
352	            Out<PeriodNumberingFrom> periodNumberingFrom, Out<GradeTerms> gradeTerms, Out<Cap> cap)
353	            throws InvalidSettingException {
354	        limit.set(clerkLimit(request.clerkLimit(), from(request.clerkLimitFrom(), "clerk limit")));
355	        floor.set(floor(request.floor(), from(request.floorFrom(), "floor")));
356	        terms.set(terms(request.terms(), from(request.termsFrom(), "terms")));
357	        latePct.set(latePct(request.latePct(), from(request.latePctFrom(), "late percent")));
358	        policyDate.set(policyDate(request.policyDate()));
359	        periodNumberingFrom.set(periodNumberingFrom(request.periodNumberingFrom()));
360	        gradeTerms.set(gradeTerms(request.gradeTerms(), request.gradeTermsFrom()));
361	        cap.set(cap(request.cap(), from(request.capFrom(), "cap")));
362	    }
363	
364	    /** A from-date typed with a setting (null: left out or blank, the sheet's today). */
365	    private static LocalDate from(String requested, String what) throws InvalidSettingException {
366	        String value = requested == null ? "" : requested.trim();
367	        if (value.isEmpty()) {
368	            return null;
369	        }
370	        try {
371	            return LocalDate.parse(value);
372	        } catch (DateTimeParseException e) {
373	            throw new InvalidSettingException("The " + what + " from-date must be a date (yyyy-MM-dd), or blank.");
374	        }
375	    }
376	
377	    private static Cap cap(String requested, LocalDate from) throws InvalidSettingException {
378	        if (requested == null) {
379	            return new Cap(false, null, null);
380	        }
381	        String value = requested.trim();
382	        if (value.isEmpty()) {
383	            return new Cap(true, null, from);
384	        }
385	        if (!AMOUNT.matcher(value).matches()) {
386	            throw new InvalidSettingException("The cap must be 0.00 or more, with at most two decimals, or blank.");
387	        }
388	        return new Cap(true, new BigDecimal(value).setScale(2), from);
389	    }
390	
391	    private static ClerkLimit clerkLimit(String requested, LocalDate from) throws InvalidSettingException {
392	        if (requested == null) {
393	            return new ClerkLimit(false, null, null);
394	        }
395	        String value = requested.trim();
396	        if (value.isEmpty()) {
397	            return new ClerkLimit(true, null, from);
398	        }
399	        if (!AMOUNT.matcher(value).matches()) {
400	            throw new InvalidSettingException("The clerk limit must be 0.00 or more, with at most two decimals, or blank.");
401	        }
402	        return new ClerkLimit(true, new BigDecimal(value).setScale(2), from);
403	    }
404	
405	    private static Terms terms(String requested, LocalDate from) throws InvalidSettingException {
406	        if (requested == null) {
407	            return new Terms(null, null);
408	        }
409	        String value = requested.trim();
410	        if (value.isEmpty()) {
411	            return new Terms(SettingRepository.DEFAULT_TERMS, from);
412	        }
413	        if (!DAYS.matcher(value).matches()) {
414	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more, or blank.");
415	        }
416	        return new Terms(Integer.parseInt(value), from);
417	    }
418	
419	    private static GradeTerms gradeTerms(Map<String, String> requested, Map<String, String> requestedFrom)
420	            throws InvalidSettingException {
421	        Map<String, Integer> terms = new LinkedHashMap<>();
422	        Map<String, LocalDate> from = new LinkedHashMap<>();
423	        if (requested == null) {
424	            return new GradeTerms(terms, from);
425	        }
426	        for (String grade : requested.keySet().stream().sorted().toList()) {
427	            if (!GRADES.contains(grade)) {
428	                throw new InvalidSettingException("Terms can only be set for grade A, B or C.");
429	            }
430	            String value = requested.get(grade) == null ? "" : requested.get(grade).trim();
431	            if (value.isEmpty()) {
432	                terms.put(grade, null);
433	            } else if (!DAYS.matcher(value).matches()) {
434	                throw new InvalidSettingException("The terms for a grade must be a whole number of days, 0 or more, or blank.");
435	            } else {
436	                terms.put(grade, Integer.parseInt(value));
437	            }
438	            LocalDate gradeFrom = from(requestedFrom == null ? null : requestedFrom.get(grade), "grade " + grade + " terms");
439	            if (gradeFrom != null) {
440	                from.put(grade, gradeFrom);
441	            }
442	        }
443	        return new GradeTerms(terms, from);
444	    }
445	
446	    private static LatePct latePct(String requested, LocalDate from) throws InvalidSettingException {
447	        if (requested == null) {
448	            return new LatePct(null, null);
449	        }
450	        String value = requested.trim();
451	        if (value.isEmpty()) {
452	            return new LatePct(SettingRepository.DEFAULT_LATE_PCT, from);
453	        }
454	        if (!PERCENT.matcher(value).matches()) {
455	            throw new InvalidSettingException("The late percent must be 0.00 or more, with at most two decimals, or blank.");
456	        }
457	        return new LatePct(new BigDecimal(value).setScale(2), from);
458	    }
