461	        if (requested == null) {
462	            return new PolicyDate(false, null);
463	        }
464	        String value = requested.trim();
465	        if (value.isEmpty()) {
466	            return new PolicyDate(true, null);
467	        }
468	        try {
469	            return new PolicyDate(true, LocalDate.parse(value));
470	        } catch (DateTimeParseException e) {
471	            throw new InvalidSettingException("The policy date must be a date (yyyy-MM-dd), or blank.");
472	        }
473	    }
474	
475	    private static PeriodNumberingFrom periodNumberingFrom(String requested) throws InvalidSettingException {
476	        if (requested == null) {
477	            return new PeriodNumberingFrom(false, null);
478	        }
479	        String value = requested.trim();
480	        if (value.isEmpty()) {
481	            return new PeriodNumberingFrom(true, null);
482	        }
483	        try {
484	            return new PeriodNumberingFrom(true, LocalDate.parse(value));
485	        } catch (DateTimeParseException e) {
486	            throw new InvalidSettingException("The period numbering from date must be a date (yyyy-MM-dd), or blank.");
487	        }
488	    }
489	
490	    private static Floor floor(String requested, LocalDate from) throws InvalidSettingException {
491	        if (requested == null) {
492	            return new Floor(null, null);
493	        }
494	        String value = requested.trim();
495	        if (value.isEmpty()) {
496	            return new Floor(SettingRepository.DEFAULT_FLOOR, from);
497	        }
498	        if (!AMOUNT.matcher(value).matches()) {
499	            throw new InvalidSettingException("The floor must be 0.00 or more, with at most two decimals, or blank.");
