505	package net.officefloor.hq.app.setting;
506	
507	import java.math.BigDecimal;
508	import java.time.LocalDate;
509	import java.sql.Date;
510	import java.util.LinkedHashMap;
511	import java.util.List;
512	import java.util.Map;
513	import java.util.NavigableMap;
514	import java.util.TreeMap;
515	import net.officefloor.hq.app.claim.Claim;
516	import net.officefloor.hq.app.claim.Rounding;
517	import org.springframework.jdbc.core.JdbcTemplate;
518	import org.springframework.stereotype.Repository;
519	
520	@Repository
521	public class SettingRepository {
522	
523	    /** The floor a sheet starts with. */
524	    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");
525	
526	    /** The terms a sheet starts with, in days. */
527	    public static final int DEFAULT_TERMS = 14;
528	
529	    /** The late percent a sheet starts with. */
530	    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");
531	
532	    private final JdbcTemplate jdbc;
533	
534	    public SettingRepository(JdbcTemplate jdbc) {
535	        this.jdbc = jdbc;
536	    }
537	
538	    /** The sheet's settings: the dated ones in force on its today (and every value recorded), its policy date, its period numbering from date and its roles, by user name. */
539	    public Settings find(String sheetId) {
540	        List<UserRole> roles = jdbc.query("SELECT sheet_id, user_name, role FROM user_role WHERE sheet_id = ?"
541	                + " ORDER BY user_name", (rs, n) -> new UserRole(rs.getString("sheet_id"), rs.getString("user_name"),
542	                        Role.valueOf(rs.getString("role"))), sheetId);
543	        List<Date> found = jdbc.query("SELECT today FROM sheet WHERE id = ?", (rs, n) -> rs.getDate("today"), sheetId);
544	        LocalDate today = found.isEmpty() || found.get(0) == null ? LocalDate.now() : found.get(0).toLocalDate();
545	        DatedSettings dated = dated(sheetId);
546	        return new Settings(sheetId, dated.clerkLimitOn(today), dated.floorOn(today), dated.termsOn(today),
547	                dated.gradeTermsOn(today), dated.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId),
548	                dated.capOn(today), roles, dated);
549	    }
550	
551	    /** The sheet's dated settings: every value recorded, by key and from-date. */
552	    public DatedSettings dated(String sheetId) {
553	        Map<String, NavigableMap<LocalDate, String>> values = new LinkedHashMap<>();
554	        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_from WHERE sheet_id = ?"
555	                + " ORDER BY setting_key, from_date", (rs) -> {
556	                    values.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
557	                            .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value"));
558	                }, sheetId);
559	        return new DatedSettings(values);
560	    }
561	
562	    /** Record the key's value from the date (null: blank), replacing any value already recorded from that date. */
563	    public void saveDated(String sheetId, String key, LocalDate from, String value) {
564	        jdbc.update("DELETE FROM setting_from WHERE sheet_id = ? AND setting_key = ? AND from_date = ?",
565	                sheetId, key, Date.valueOf(from));
566	        jdbc.update("INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value) VALUES (?, ?, ?, ?)",
567	                sheetId, key, Date.valueOf(from), value);
568	    }
569	
570	    /** The sheet's rounding policy date as set (null: blank, the sheet's today). */
571	    public LocalDate policyDate(String sheetId) {
572	        List<Date> date = jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
573	                (rs, n) -> rs.getDate("policy_date"), sheetId);
574	        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
575	    }
576	
577	    /** How the sheet rounds the given claims' live figures on the given today: by its policy date (blank: today). */
578	    public Rounding rounding(String sheetId, LocalDate today, List<Claim> claims) {
579	        LocalDate policyDate = policyDate(sheetId);
580	        return Rounding.of(policyDate == null ? today : policyDate, claims);
581	    }
582	
583	    /** Set the sheet's rounding policy date (null: blank, the sheet's today). */
584	    public void savePolicyDate(String sheetId, LocalDate policyDate) {
585	        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", policyDate == null ? null : Date.valueOf(policyDate), sheetId);
586	    }
587	
588	    /** The sheet's period numbering from date (null: blank, off). */
589	    public LocalDate periodNumberingFrom(String sheetId) {
590	        List<Date> date = jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
591	                (rs, n) -> rs.getDate("period_numbering_from"), sheetId);
592	        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
593	    }
594	
595	    /** Set the sheet's period numbering from date (null: blank, off). */
596	    public void savePeriodNumberingFrom(String sheetId, LocalDate from) {
597	        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", from == null ? null : Date.valueOf(from), sheetId);
598	    }
599	
600	    /** Give the user name its role on the sheet, replacing any it had. */
601	    public void saveRole(UserRole role) {
602	        int updated = jdbc.update("UPDATE user_role SET role = ? WHERE sheet_id = ? AND user_name = ?",
603	                role.role().name(), role.sheetId(), role.user());
604	        if (updated == 0) {
605	            jdbc.update("INSERT INTO user_role (sheet_id, user_name, role) VALUES (?, ?, ?)",
606	                    role.sheetId(), role.user(), role.role().name());
607	        }
608	    }
609	}
