import { useSheetToday } from '../session/sheetToday';
import { deferred } from './claims';
import type { Claim } from './claims';

// Whether a claim is deferred on the sheet's today, and the date it is deferred until (blank when it is not).
export function ClaimDeferred({ claim }: { claim: Claim }) {
  const today = useSheetToday();
  const is = deferred(claim, today);
  return (
    <>
      <span data-testid="claim-deferred">{is ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-deferred-until">{is ? claim.deferredUntil : ''}</span>
    </>
  );
}
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { ClaimDeferred } from './ClaimDeferred';

export const contribution = ClaimRowValues.fill({ order: 14, Component: ClaimDeferred });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { covers } from '../people/people';
import type { Hold } from '../people/people';
import { sheetKey, useCurrentSheet } from '../session/session';

/**
 * Where a claim is in its life: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit makes it
 * PENDING, which a steward approves (SETTLED) or rejects (OPEN); DRAFT, OPEN or PENDING -> VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** Whether a claim is open: OPEN, or PENDING (handled like an open claim). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim is deferred on the sheet's `today`: OPEN, deferred until a date after it. A deferred claim counts
 * in no total, is not overdue, cannot be settled and is left unbound by a statement.
 */
export const deferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== '' && today < c.deferredUntil;

/** Whether a statement binds the claim now: it was stated and is not PENDING (a pending claim shows its live figure). */
export const bound = (c: Claim) => c.stated && c.status !== 'PENDING';

/**
 * A claim as the store holds it: the amount with two decimals, the date as yyyy-MM-dd; its number
 * is the sheet's next one when it was opened (1, 2, ...; under period numbering, the next within its period: P1-1, X-1), null while a draft (a voided claim keeps it); its due is the
 * one fixed when it was settled (two decimals), null while it is live; openedBy is the user who
 * opened it, null while a draft; stated is whether its person's last statement bound it to a figure,
 * statedDue that figure (two decimals; null: n/a) — it then shows and totals that, not its live figure;
 * corrects is, for a correction (a negative amount), the number of the settled claim it corrects, null otherwise;
 * dueBy (yyyy-MM-dd) is fixed when it was created: its date plus the terms of its person's grade in force on it;
 * log is its status log, oldest first: each status it has had, the user who gave it, the sheet's today then and its due then;
 * deferredUntil (yyyy-MM-dd) is the date it was deferred until, null when it never was.
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: ClaimLogLine[];
  deferredUntil: string | null;
};

/** A line of a claim's status log: the status, the user, the sheet's today (yyyy-MM-dd) and the due then (two decimals, or n/a). */
export type ClaimLogLine = { status: ClaimStatus; by: string; date: string; due: string };

/**
 * Whether a claim counts toward claimed, due-total and every live total: only OPEN, PENDING and SETTLED do,
 * and an open (or pending) one not when one of its person's `holds` covers its date and no statement binds it,
 * nor while it is deferred on the sheet's `today`.
 */
export const counts = (c: Claim, holds: Hold[], today: string) =>
  c.status === 'SETTLED' ||
  (isOpen(c) && !deferred(c, today) && (bound(c) || !holds.some((h) => covers(h, c.date))));

/** Each person's holds, by id: their open claims dated within one count in no live total. */
export const holdsById = (people: { id: number; holds: Hold[] }[]) => new Map(people.map((p) => [p.id, p.holds]));

/** The fields the claim form submits; a blank date is the sheet's today; corrects names, by number, the claim a correction corrects. */
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d+(\.\d{1,2})?|\.\d{1,2})$/;

/** An amount the claim form takes: negative for a correction, with at most two decimals. */
export const SIGNED_AMOUNT = /^-?(\d+(\.\d{1,2})?|\.\d{1,2})$/;

/** The query key for the sheet's claims; under sheetKey, so re-loading the sheet re-reads them. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: !!sheet,
  });
}

/** The sum of the counted claims' amounts, with two decimals; added in cents so it is exact. `holds` holds each person's holds. */
export function claimed(claims: Claim[], holds: Map<number, Hold[]>, today: string): string {
  const cents = claims.filter((c) => counts(c, holds.get(c.personId) ?? [], today)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { defineSlot } from '../Slot';
import type { Claim } from '../../features/claims/claims';
import type { Person } from '../../features/people/people';

/** Extra values shown in a claim's row, after its note: each contribution renders its own inline element. */
export const ClaimRowValues = defineSlot<{ claim: Claim; person: Person }>('claims.rowValues');
import { useCallback, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useClaims } from '../claims/claims';

/** A role given to a user name: clerk or steward. A name with none given is a clerk. */
export type UserRole = { user: string; role: string };

/**
 * The sheet's settings as the store holds them: the clerk limit (two decimals; null: no limit), above
 * which a clerk cannot settle a claim, the floor (two decimals), below which no live due goes, the terms
 * (whole days) a claim is due by after its date, the terms set
 * for each grade that has its own (by grade; any other grade uses the sheet's terms), the late percent (two decimals) an overdue claim
 * gains of its figure every full 30 days, the rounding policy date (yyyy-MM-dd; '': blank, the
 * sheet's today), the period numbering from date (yyyy-MM-dd; '': off — on or after it, an opened claim is
 * numbered within its period), the cap (two decimals; '': none — a person's due-total is at most it), and the roles
 * given to user names. The clerk limit, floor, terms, grade terms, late percent and cap are those in force on the sheet's
 * today; `history` holds every value recorded for them, by key (floor, late-pct, terms, terms-<grade>, clerk-limit,
 * cap), oldest from-date first (value '': blank).
 */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; gradeTerms: Record<string, number>; latePct: string; policyDate: string; periodNumberingFrom: string; cap: string; roles: UserRole[]; history: Record<string, FromValue[]> };

/** A dated setting's value recorded from a date (yyyy-MM-dd); '': blank. */
export type FromValue = { from: string; value: string };

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else `start`. */
export function valueOn(history: FromValue[] | undefined, date: string, start: string): string {
  let found = start;
  for (const v of history ?? []) {
    if (v.from <= date) found = v.value === '' ? start : v.value;
  }
  return found;
}

/** The floor a sheet starts with: a claim's live due is at least it. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days: a claim is due by its date plus them. */
export const DEFAULT_TERMS = 14;

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The roles a user name can be given. */
export const ROLES = ['clerk', 'steward'];

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d{1,13}(\.\d{1,2})?|\.\d{1,2})$/;

/** A percent: 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** 0 or more whole days. */
export const DAYS = /^\d{1,5}$/;

/** The query key for the sheet's settings; under sheetKey, so re-loading the sheet re-reads them. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

/** The sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: !!sheet,
  });
}

/** The sheet's floor (two decimals): a claim's live due is at least it. */
export function useFloor(): string {
  return useSettings().data?.floor ?? DEFAULT_FLOOR;
}


/** A date as the settings form takes it: yyyy-MM-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * What a claim's due is worked out from: the floor and late percent in force on a claim's date, the sheet's today, its policy
 * date in force (blank: today), its cap in force on today ('': none) and the dates of its claims by number (a correction rounds by the date
 * of the claim it corrects).
 */
export type DueRules = {
  floorOn: (date: string) => string;
  latePctOn: (date: string) => string;
  today: string;
  policyDate: string;
  cap: string;
  claimDates: Map<string, string>;
};

/** The sheet's rules for working out a claim's due. */
export function useDueRules(): DueRules {
  const settings = useSettings().data;
  const today = useSheetToday();
  const claims = useClaims().data;
  const claimDates = useMemo(
    () => new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number!, c.date])),
    [claims],
  );
  const history = settings?.history;
  const floorOn = useCallback((date: string) => valueOn(history?.floor, date, DEFAULT_FLOOR), [history]);
  const latePctOn = useCallback((date: string) => valueOn(history?.['late-pct'], date, DEFAULT_LATE_PCT), [history]);
  return {
    floorOn,
    latePctOn,
    today,
    policyDate: settings?.policyDate || today,
    cap: settings?.cap ?? '',
    claimDates,
  };
}

